/**
 * Debounces a function, allowing it to be called at most once within a specified delay.
 * Supports cancellation and preserves argument types.
 */
function debounce<T extends any[], K extends (...args: T) => any>(
  func: K,
  delay: number
): (arg: T) => void {
  let timeoutId: NodeJS.Timeout | null = null;
  let lastArgs: T | null = null;
  let lastThis: any = null;

  return function debounced(...args: T) {
    lastArgs = args;
    lastThis = this;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      if (lastArgs && lastThis) {
        func.apply(lastThis, lastArgs);
        lastArgs = null;
        lastThis = null;
      }
      timeoutId = null;
    }, delay);
  };
}


/**
 * Cancels a debounced function.  Resets the timeout and clears any stored arguments.
 */
function debounceCancel<T extends any[], K extends (...args: T) => any>(
  debounced: ReturnType<typeof debounce<T, K>>,
  func: K
): void {
  if (timeoutId) {
    clearTimeout(timeoutId);
    timeoutId = null;
    lastArgs = null;
    lastThis = null;
  }
}

