type DebounceFn<T extends (...args: any[]) => any> = (...args: Parameters<T>) => ReturnType<T>;

interface DebounceOptions<T extends (...args: any[]) => any> {
  delay: number;
  onResolve?: (value: ReturnType<T>) => void;
  onCancel?: (error: any) => void;
}

class Debounce<T extends (...args: any[]) => any> {
  private timerId: number | null = null;
  private callback: T | null = null;
  private options: DebounceOptions<T>;

  constructor(callback: T, options: DebounceOptions<T> = {}) {
    this.callback = callback;
    this.options = { ...options, onResolve: options.onResolve || ((value) => {}), onCancel: options.onCancel || ((error) => {}) };
  }

  public cancel(): void {
    if (this.timerId) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
  }

  public start(): DebounceFn<Parameters<T>> {
    return (...args: Parameters<T>) => {
      this.cancel(); // Clear any existing timer

      this.timerId = setTimeout(() => {
        const result = this.callback(...args);
        if (result) {
          this.options.onResolve(result);
        }
      }, this.options.delay);
    };
  }
}

export default Debounce;
```

**Explanation:**

1.  **`DebounceFn` Type:** Defines the type for the debounced function, ensuring it has the same argument types and return type as the original callback.
2.  **`DebounceOptions` Interface:**  Specifies the options for the debounce, including `delay` and optional `onResolve` and `onCancel` callbacks.
3.  **`Debounce` Class:**
    *   `timerId`: Stores the timeout ID for cancellation.
    *   `callback`: Stores the original callback function.
    *   `options`: Stores the debounce options.
    *   `constructor`: Initializes the debounce with the callback and options.
    *   `cancel()`: Clears the timeout if it exists.
    *   `start()`: Returns a new debounced function.  It cancels any existing timer and sets a new one using `setTimeout`.  If the callback executes, it calls the `onResolve` callback.

